# -*- coding: utf-8 -*-
from odoo import api, fields, models


class AccountMove(models.Model):
    _inherit = 'account.move'

    authorization_number = fields.Char(
        string='Authorization Number',
        compute='_compute_authorization_number',
        store=True,
        help=(
            "Authorization Number of the customer payment or receipt voucher this journal "
            "entry originates from (including payments generated by Point of Sale). Shown "
            "here for visibility and used by the bank reconciliation engine to automatically "
            "match this entry with the corresponding bank statement line."
        ),
    )

    @api.depends('origin_payment_id.authorization_number', 'voucher_id.authorization_number')
    def _compute_authorization_number(self):
        for move in self:
            move.authorization_number = (
                move.origin_payment_id.authorization_number or move.voucher_id.authorization_number
            )
